const u = $("Telegram Trigger").first().json;
let telegramId = '';
let firstName = '';
let text = '';
let data = '';
let callbackQueryId = '';
if (u.message) {
  telegramId = String(u.message.chat.id);
  firstName = u.message.chat.first_name || (u.message.from && u.message.from.first_name) || '';
  text = (u.message.text || '').trim();
} else if (u.callback_query) {
  telegramId = String(u.callback_query.from.id);
  firstName = u.callback_query.from.first_name || '';
  data = (u.callback_query.data || '').trim();
  callbackQueryId = u.callback_query.id;
}
return [{ json: { telegramId, firstName, text, data, callbackQueryId } }];

const p = $('Parse Update').item.json;
const sessionRow = ($json && Object.keys($json).length) ? $json : {};
let cart = [];
try { cart = sessionRow.carrito_temporal ? JSON.parse(sessionRow.carrito_temporal) : []; } catch (e) { cart = []; }

// Combine button data and typed text into a single command string
const raw = ((p.data || '') + ' ' + (p.text || '')).trim();
const cmd = raw.trim();
const lower = cmd.toLowerCase();

let action = 'help';
let category = '';
let productId = '';

// Helper: pull the token after ADD / CAT even if ':' or space is missing
function grab(prefix) {
  const re = new RegExp('^' + prefix + '[\\s:]*', 'i');
  return cmd.replace(re, '').trim();
}

if (lower === '/start' || lower === 'menu' || cmd === 'MENU') {
  action = 'menu';
} else if (/^cat[\s:]/i.test(cmd)) {
  action = 'category';
  category = grab('cat');
} else if (/^(bebidas|comidas|snacks)$/i.test(cmd)) {
  action = 'category';
  category = cmd.charAt(0).toUpperCase() + cmd.slice(1).toLowerCase();
} else if (/^add/i.test(cmd)) {
  action = 'add';
  productId = grab('add').toUpperCase();
} else if (cmd === 'CONFIRM' || /^confirmar/i.test(cmd)) {
  action = 'confirm';
} else if (cmd === 'STATUS' || /^estado/i.test(cmd)) {
  action = 'status';
} else if (cmd === 'PUNTOS' || /^puntos/i.test(cmd) || lower === 'ver mis puntos' || cmd === '4') {
  action = 'points';
}

return [{ json: {
  telegramId: p.telegramId,
  firstName: p.firstName,
  action,
  category,
  productId,
  cart: JSON.stringify(cart),
} }];

const items = $input.all().map(i => i.json).filter(r => r && r.id_producto);
const r = $('Router').item.json;
if (!items.length) {
  return [{ json: { telegramId: r.telegramId, message: 'No hay productos disponibles en la categoría ' + r.category + '.' } }];
}
const lines = items.map(p => '[' + p.id_producto + '] ' + p.nombre + ' - $' + (Number(p.precio) || 0).toFixed(2) + ' (stock: ' + p.stock + ')').join('\n');
const message = '📋 ' + r.category + '\n\n' + lines + '\n\nPara agregar un producto escribe: ADD:<id>\nEjemplo: ADD:' + items[0].id_producto;
return [{ json: { telegramId: r.telegramId, message } }];

const prod = ($json && $json.id_producto) ? $json : null;
const r = $('Router').item.json;
let cart = [];
try { cart = JSON.parse(r.cart || '[]'); } catch (e) { cart = []; }

if (!prod) {
  return [{ json: { ok: false, telegramId: r.telegramId, carrito_temporal: JSON.stringify(cart), message: '❌ Producto no encontrado. Escribe /start para ver el menú.' } }];
}
const stock = Number(prod.stock) || 0;
const yaEnCarrito = cart.filter(i => i.id === prod.id_producto).reduce((s, i) => s + (Number(i.cantidad) || 0), 0);
if (yaEnCarrito + 1 > stock) {
  return [{ json: { ok: false, telegramId: r.telegramId, carrito_temporal: JSON.stringify(cart), message: '⚠️ Lo sentimos, no hay suficiente stock de ' + prod.nombre + '. Disponible: ' + stock + ', en tu carrito: ' + yaEnCarrito + '.' } }];
}
const qty = 1;
cart.push({ id: prod.id_producto, nombre: prod.nombre, precio: Number(prod.precio) || 0, cantidad: qty });
const total = cart.reduce((s, i) => s + i.precio * i.cantidad, 0);
const resumen = cart.map(i => i.cantidad + 'x ' + i.nombre + ' ($' + (i.precio * i.cantidad).toFixed(2) + ')').join('\n');
return [{ json: {
  ok: true,
  telegramId: r.telegramId,
  carrito_temporal: JSON.stringify(cart),
  total: total.toFixed(2),
  message: '✅ Agregado: ' + prod.nombre + '\n\n🛒 Tu carrito:\n' + resumen + '\n\nTotal: $' + total.toFixed(2) + '\n\nEscribe "confirmar" para procesar o sigue agregando productos.',
} }];

const r = $('Router').first().json;
let cart = [];
try { cart = JSON.parse(r.cart || '[]'); } catch (e) { cart = []; }
if (!cart.length) {
  return [{ json: { ok: false, empty: true, telegramId: r.telegramId, message: '🛒 Tu carrito está vacío. Escribe /start para ver el menú.' } }];
}

// Build available-stock map from the MENU sheet (immediate input)
const menu = $input.all().map(i => i.json).filter(m => m && m.id_producto);
const stockById = {};
const nameById = {};
for (const m of menu) {
  stockById[m.id_producto] = Number(m.stock) || 0;
  nameById[m.id_producto] = m.nombre;
}

// Sum requested quantity per product across the cart
const reqById = {};
for (const it of cart) {
  reqById[it.id] = (reqById[it.id] || 0) + (Number(it.cantidad) || 0);
}

// Validate stock
const problems = [];
for (const id in reqById) {
  const disponible = stockById[id] || 0;
  const pedido = reqById[id];
  if (pedido > disponible) {
    const nombre = nameById[id] || (cart.find(c => c.id === id) || {}).nombre || id;
    problems.push('• ' + nombre + ': pediste ' + pedido + ', disponible ' + disponible);
  }
}
if (problems.length) {
  return [{ json: { ok: false, empty: false, insufficientStock: true, telegramId: r.telegramId, message: '⚠️ No pudimos procesar tu pedido por falta de stock:\n\n' + problems.join('\n') + '\n\nAjusta tu carrito e inténtalo de nuevo.' } }];
}

// Stock OK -> build order + stock updates
const stockUpdates = [];
for (const id in reqById) {
  stockUpdates.push({ id_producto: id, stock: (stockById[id] || 0) - reqById[id] });
}
const total = cart.reduce((s, i) => s + i.precio * i.cantidad, 0);
const now = new Date();
const fecha = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota', year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
const hora = new Intl.DateTimeFormat('en-GB', { timeZone: 'America/Bogota', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false }).format(now);
const id_pedido = 'ORD-' + now.getTime().toString().slice(-8);
const detalles = cart.map(i => i.cantidad + 'x ' + i.nombre).join(', ');
return [{ json: {
  ok: true,
  empty: false,
  id_pedido: id_pedido,
  id_usuario: r.telegramId,
  telegramId: r.telegramId,
  detalles_pedido: JSON.stringify(cart),
  detalles_texto: detalles,
  total_pago: total.toFixed(2),
  estado: 'Recibido',
  fecha: fecha,
  hora: hora,
  stock_updates: JSON.stringify(stockUpdates),
  message: '🎉 ¡Pedido confirmado!\n\nN° de orden: ' + id_pedido + '\n' + detalles + '\nTotal: $' + total.toFixed(2) + '\nEstado: Recibido\n\nTe avisaremos cuando esté en preparación. 👨‍🍳',
} }];

