let arr = [];
try { arr = JSON.parse($json.stock_updates || '[]'); } catch (e) { arr = []; }
if (!arr.length) return [];
return arr.map(u => ({ json: { id_producto: u.id_producto, stock: u.stock } }));

const rows = $input.all().map(i => i.json).filter(r => r && r.id_pedido);
const r = $('Router').item.json;
if (!rows.length) {
  return [{ json: { telegramId: r.telegramId, message: 'No tienes pedidos registrados aún. Escribe /start para hacer tu primer pedido.' } }];
}
const last = rows[rows.length - 1];
const message = '📦 Tu último pedido\n\nN° ' + last.id_pedido + '\nTotal: $' + last.total_pago + '\nEstado: ' + last.estado + '\nFecha: ' + last.fecha + ' ' + last.hora;
return [{ json: { telegramId: r.telegramId, message } }];

const raw = $json || {};
const found = raw['telegram_id        '] !== undefined || raw.telegram_id !== undefined;
const u = found ? raw : {};
const r = $('Router').item.json;
const nombre = u.nombre_completo || r.firstName || 'cliente';
const puntos = Number(u.puntos_lealtad) || 0;
const message = 'Hola ' + nombre + ', actualmente tienes 🏆 ' + puntos + ' puntos acumulados. ¡Sigue comprando para canjear premios!';
return [{ json: { telegramId: r.telegramId, message } }];

const rows = $input.all().map(i => i.json).filter(r => r && r.id_pedido);
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const todays = rows.filter(r => (r.fecha || '') === today);
let total = 0;
const prodCount = {};
const hourCount = {};
for (const r of todays) {
  total += Number(r.total_pago) || 0;
  const h = (r.hora || '00').slice(0, 2);
  hourCount[h] = (hourCount[h] || 0) + 1;
  try {
    const cart = JSON.parse(r.detalles_pedido || '[]');
    for (const it of cart) { prodCount[it.nombre] = (prodCount[it.nombre] || 0) + (Number(it.cantidad) || 0); }
  } catch (e) {}
}
let star = 'N/A', max = 0;
for (const k in prodCount) { if (prodCount[k] > max) { max = prodCount[k]; star = k; } }
let peak = 'N/A', pm = 0;
for (const k in hourCount) { if (hourCount[k] > pm) { pm = hourCount[k]; peak = k + ':00'; } }
const message = '📊 Reporte diario DeliveryBot (' + today + ')\n\nPedidos: ' + todays.length + '\nTotal vendido: $' + total.toFixed(2) + '\nProducto estrella: ' + star + '\nHora pico: ' + peak;
return [{ json: { message, total: total.toFixed(2), star, peak, pedidos: todays.length } }];
